from collections import Counter, defaultdict


def word_count_pipeline(text):
    words = text.lower().split()
    counts = Counter(words)
    return counts.most_common(3)


def csv_aggregate(rows, group_col, value_col):
    totals = defaultdict(int)
    for row in rows:
        totals[row[group_col]] += row[value_col]
    return dict(totals)


def top_cooccurrences(pairs, n):
    counts = Counter(frozenset(pair) for pair in pairs)
    return counts.most_common(n)
